#!/usr/bin/env python3
# Generates Tests/Compiler/Srm32AuditExpected.lean from the Lean text frozen in scripts/srm32/EXPECTED.txt (independent of the proof files).
HDR = """import Tests.Compiler.Srm32InstTest
set_option autoImplicit false
-- GENERATED by scripts/srm32/gen_exp.py from scripts/srm32/EXPECTED.txt (committed before any Lean edit); fully qualified, independent of the proof files.
namespace Tests.Compiler.Srm32AuditExpected
open Sparkle.IR.AST
open Tools.ShippingMachineEntry (MachineWired)
open Sparkle.IR.Machine (SlotField)

/-- EXPECTED §1: the new LAST clause (20th) of `MachineWired` at the generic names. -/
def Exp_lastClause (shape : Sparkle.Compiler.Elab.MachineShape) (m : Module) (regs : List String) : Prop :=
  ∀ (k : Nat) (r : String) (f : SlotField), regs[k]? = some r →
    shape.layout.slots[k]? = some f → Tools.ShippingEntrySoundness.weOf m r = f.width
/-- NEGATIVE FIXTURE for the clause: weakened to `≤` (must NOT be defeq to the 20th conjunct). -/
def Exp_mut_lastClause_le (shape : Sparkle.Compiler.Elab.MachineShape) (m : Module) (regs : List String) : Prop :=
  ∀ (k : Nat) (r : String) (f : SlotField), regs[k]? = some r →
    shape.layout.slots[k]? = some f → Tools.ShippingEntrySoundness.weOf m r ≤ f.width

def WBND (extra : String) : String:= ""
"""
WIRED = """{declName : Lean.Name} {shape : Sparkle.Compiler.Elab.MachineShape} {ids : List Lean.FVarId}
    {cache : IO.Ref (Lean.ExprStructMap String)} {m %s: Module} {dsn : Design} {regs lets : List String}"""
def wb(b): return WIRED % ("b " if b else "")
HW = "(hW : MachineWired declName shape ids cache m dsn regs lets)"
POST = "(hpost : b = Sparkle.IR.ZeroWidth.dropZeroWidthModule m ∨ b = Sparkle.IR.RefineCheck.mergeChecked (Sparkle.IR.ZeroWidth.dropZeroWidthModule m))"
GATE = "(hgate : Sparkle.IR.RefineCheck.hierGate b = true)"
OUTTY = "(houtTy : ∀ o ∈ shape.layout.outs, o.ty.bitWidth = o.width)"
CONC_W = "∀ (k : Nat) (r : String) (f : SlotField), regs[k]? = some r →\n      shape.layout.slots[k]? = some f → Tools.ShippingEntrySoundness.weOf m r = f.width"
CONC_D = "∀ (k : Nat) (r : String) (f : SlotField), regs[k]? = some r →\n      shape.layout.slots[k]? = some f → f.width ≤ Sparkle.IR.RegDedup.declWidth b r"
def d(name, binders, hw, concl, bflag): return f"def {name} : Prop :=\n  ∀ {wb(bflag)}\n    {binders} {hw},\n    {concl}\n"
out = HDR
out += d("Exp_slotWidths","", HW, CONC_W, False).replace("  ∀ {declName","  ∀ {declName").replace("\n     (hW","\n    (hW")
out += d("Exp_hWd", f"{POST} {GATE} {OUTTY}", HW, CONC_D, True)
out += "-- NEGATIVE FIXTURES of Exp_hWd (must be rejected)\n"
out += d("Exp_mut_withTrue", f"{POST} {GATE} {OUTTY}", HW.replace("dsn regs lets)","dsn regs lets ∧ True)"), CONC_D, True)
out += d("Exp_mut_addedBinder", f"{POST} {GATE} {OUTTY} (extra : Nat)", HW, CONC_D, True)
out += d("Exp_mut_reordered", f"{GATE} {POST} {OUTTY}", HW, CONC_D, True)
out += d("Exp_mut_noOutTy", f"{POST} {GATE}", HW, CONC_D, True)
out += d("Exp_mut_lt", f"{POST} {GATE} {OUTTY}", HW, CONC_D.replace("f.width ≤","f.width <"), True)
out += d("Exp_mut_slotWidths_withTrue","", HW.replace("dsn regs lets)","dsn regs lets ∧ True)"), CONC_W, False)
out += d("Exp_mut_slotWidths_le","", HW, CONC_W.replace("= f.width","≤ f.width"), False)
out += "\nopen Tests.Compiler.SharedLeafMemKidTest (topshareM topshareQ)\nopen Tests.Compiler.Srm9ComposedTest (TmBnd TqBnd tmExt tmExtB tqExt tqExtB)\nopen Tools.ShippingSrm28 (ComposedNWRegs)\n"
def inst(name, X, B, ext, extB, P, hpost=True):
    hp = "    (hpost : b = Sparkle.IR.ZeroWidth.dropZeroWidthModule raw ∨ b = Sparkle.IR.RefineCheck.mergeChecked (Sparkle.IR.ZeroWidth.dropZeroWidthModule raw))\n" if hpost else ""
    return f"""def {name} : Prop :=
  ∀ {{mctx : Lean.Meta.Context}} {{mref : ST.Ref IO.RealWorld Lean.Meta.State}} {{cctx : Lean.Core.Context}} {{cref : ST.Ref IO.RealWorld Lean.Core.State}}
    {{w w1 : Void IO.RealWorld}} {{b raw : Module}} {{D : Design}}
    (hcore : Tools.ShippingEntrySoundness.RunsTo (Sparkle.Compiler.Elab.synthesizeCombinationalCore ``topshare{X} [] false) mctx mref cctx cref w (raw, D) w1)
{hp}    (entry : Tools.ShippingMachineEntry.MachineDefines mctx mref cctx cref ``topshare{X} topshare{X}.machineData.shape)
    (hBnd : {B} mctx mref cctx cref w raw D),
    ComposedNWRegs 2 ``topshare{X} topshare{X}.machineData 4 raw D (fun _ : Unit => Sparkle.Core.Domain.defaultDomain) topshare{X}.machineSource {ext} {extB}
      {P}
"""
def PW(X): return f"(fun regs => ∀ (k : Nat) (r : String) (f : SlotField), regs[k]? = some r →\n        topshare{X}.machineData.shape.layout.slots[k]? = some f → f.width ≤ Sparkle.IR.RegDedup.declWidth b r)"
out += "\n" + inst("Exp_M_hWd","M","TmBnd","tmExt","tmExtB",PW("M"))
out += "\n" + inst("Exp_Q_hWd","Q","TqBnd","tqExt","tqExtB",PW("Q"))
out += "\n-- NEGATIVE FIXTURES of Exp_M_hWd (must be rejected): P := True; hpost dropped; ≤ replaced by <\n"
out += inst("Exp_mut_M_trivialP","M","TmBnd","tmExt","tmExtB","(fun _ => True)")
out += inst("Exp_mut_M_noHpost","M","TmBnd","tmExt","tmExtB",PW("M"),hpost=False)
out += inst("Exp_mut_M_lt","M","TmBnd","tmExt","tmExtB",PW("M").replace("f.width ≤","f.width <"))
out += "\nend Tests.Compiler.Srm32AuditExpected\n"
out = out.replace('def WBND (extra : String) : String:= ""\n','')
open("Tests/Compiler/Srm32AuditExpected.lean","w",encoding="utf-8").write(out)
